#include "BackgroundHostFixtureRuntime.h"
#include <fstream>

using namespace coincide;using namespace coincide::background_host;
int wmain(int argc,wchar_t** argv){winrt::init_apartment();std::filesystem::path root;bool owned{};try{if(argc<3||argc>5)return 64;root=argv[2];if(!local_file::local_path(root))return 65;const Scope temporary(std::filesystem::temp_directory_path());auto scope=std::make_shared<Scope>(root);root=scope->directory();if(!local_file::within(temporary.directory(),root)||!root.filename().wstring().starts_with(L"Coincide-Host-IPC-"))return 65;const auto marker=local_file::read(root/L"synthetic-host-fixture.txt",128).bytes;if(marker!="COINCIDE_SYNTHETIC_HOST_FIXTURE\n"&&marker!="COINCIDE_SYNTHETIC_HOST_FIXTURE\r\n")return 66;owned=true;const std::wstring mode(argv[1]);
    if(mode==L"--host-fixture-server"&&argc==4){auto state=std::make_shared<background_host_fixture::State>();Core core(scope,[state](const Key&,const Launch&){return std::make_unique<background_host_fixture::Session>(state);});std::vector<FileIdentity> peers{file_identity(current_image()),file_identity(argv[3])};Server server(core,scope,std::move(peers));server.run();return 0;}
    if((mode==L"--host-fixture-ui"||mode==L"--host-fixture-drop")&&argc==4){const auto script=Object::Parse(winrt::to_hstring(local_file::read(argv[3],1024*1024).bytes));const auto input=command(script);if(mode==L"--host-fixture-ui"){Client client(scope);const auto result=client.call(input);std::ofstream(root/L"ui-ready.json")<<winrt::to_string(result.Stringify());for(;;)Sleep(100);}
        auto pipe=pipe_io::connect(*scope,GetTickCount64()+3000);if(!pipe)return 67;auto peer=authenticate_peer(pipe.value,false,*scope,file_identity(current_image()));Object request;request.SetNamedValue(L"version",Value::CreateNumberValue(1));put(request,L"scope",scope->id());request.SetNamedValue(L"command",script);pipe_io::send(pipe.value,winrt::to_string(request.Stringify()),GetTickCount64()+3000);std::ofstream(root/L"drop-ready.txt")<<"request sent";return 0;}
    if(mode==L"--host-fixture-stall"&&argc==3){auto pipe=pipe_io::connect(*scope,GetTickCount64()+3000);if(!pipe)return 70;std::ofstream(root/L"stall-ready.txt")<<"connected";Sleep(15000);return 0;}
    if(mode==L"--host-fixture-malformed"&&argc==3){auto pipe=pipe_io::connect(*scope,GetTickCount64()+3000);if(!pipe)return 68;std::array<char,4> oversized{0,0,0,127};pipe_io::transfer(pipe.value,true,oversized.data(),oversized.size(),GetTickCount64()+1000);return 0;}
    return 69;
}catch(const winrt::hresult_error& error){if(owned)std::ofstream(root/L"fixture-error.txt")<<winrt::to_string(error.message());return 1;}catch(const std::exception& error){if(owned)std::ofstream(root/L"fixture-error.txt")<<error.what();return 1;}}
